def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Identify cells of each color that are enclosed by that color's boundary,
    # and fill enclosed background regions with 2.
    from collections import deque

    for color in set(v for row in grid for v in row):
        if color == 9:
            continue
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                region = []
                touches_edge = False
                while q:
                    y, x = q.popleft()
                    region.append((y, x))
                    if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                        touches_edge = True
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != color and (ny,nx) not in seen:
                            seen.add((ny,nx))
                            q.append((ny,nx))
                if not touches_edge:
                    for y, x in region:
                        if grid[y][x] == 9:
                            out[y][x] = 2
    return out
